import {readFileSync,realpathSync,readdirSync} from 'node:fs';import {resolve,relative} from 'node:path';import {sha256,Interface} from 'ethers';import {APP_FILES} from './app-files.mjs';
export const REGISTRY_ABI=['function putFile(address,string,string,bytes32,bytes)','function appendChunk(address,string,uint256,bytes)','function setFallback(address,string)','function fileInfo(address,string) view returns(uint32,string,bytes32,uint40,uint256)','function readRange(address,string,uint256,uint256) view returns(bytes)'];
export function loadDewebBundle(root,dir=resolve(root,'dist/wallet')){if(realpathSync(dir)!==realpathSync(resolve(root,'dist/wallet')))throw Error('DeWEB may ONLY publish dist/wallet, never wallet-local or a directory alias');const manifest=JSON.parse(readFileSync(resolve(dir,'deweb-manifest.json')));if(manifest.mode!=='wallet'||!manifest.externalData?.length)throw Error('Public wallet manifest required');const permitted=new Set([...APP_FILES,'app-config.json']);const physical=readdirSync(dir,{recursive:true,withFileTypes:true}).filter(e=>e.isFile()).map(e=>relative(dir,resolve(e.parentPath||e.path,e.name)).replaceAll('\\','/'));if(physical.some(p=>!permitted.has(p)&&p!=='deweb-manifest.json'))throw Error('Unexpected file outside build whitelist');const files=[];for(const f of manifest.files){const path=f.path.startsWith('/')?f.path.slice(1):f.path;if(!permitted.has(path))throw Error('Unapproved DeWEB path');const bytes=readFileSync(resolve(dir,path));if(bytes.length!==f.bytes||sha256(bytes)!==f.sha256||bytes.length>8400000)throw Error('Bundle hash/size mismatch');files.push({...f,path,bytes});}if(files.length!==permitted.size)throw Error('Incomplete bundle');return {manifest,files};}
export function uploadPlan(bundle,container,registry){const i=new Interface(REGISTRY_ABI),plan=[];for(const f of bundle.files){for(let offset=0,chunk=0;offset<f.bytes.length;offset+=24000,chunk++){const data=f.bytes.subarray(offset,offset+24000);plan.push({path:f.path,chunk,to:registry,value:'0x0',data:chunk===0?i.encodeFunctionData('putFile',[container,f.path,f.contentType,f.sha256,data]):i.encodeFunctionData('appendChunk',[container,f.path,chunk,data])});}}plan.push({path:'fallback',to:registry,value:'0x0',data:i.encodeFunctionData('setFallback',[container,'index.html'])});return plan;}
